/**
 * A switch row (spec/02 §2.6): [title] in body, [help] in caption textMuted under it, the switch at the end (accent when on,
 * never lime, the check in the thumb); ≥ 56 dp, the whole row toggles, one TalkBack node with the state. [icon] = an
 * optional leading icon as a list row's lead (24 dp, textMuted), decorative: the row's name stays [title].
 */
@Composable
fun SbSwitchRow(
    title: String,
    checked: Boolean,
    onChange: (Boolean) -> Unit,
    modifier: Modifier = Modifier,
    help: String? = null,
    enabled: Boolean = true,
    icon: ImageVector? = null,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val interaction = remember { MutableInteractionSource() }
    Row(
        modifier
            .fillMaxWidth()
            .sbFocusRingInset(interaction)
            .heightIn(min = t.size.controlLg)
            .toggleable(
                value = checked,
                interactionSource = interaction,
                indication = null,
                enabled = enabled,
                role = Role.Switch,
                onValueChange = onChange,
            )
            .padding(horizontal = t.spacing.gutter, vertical = t.space.s2),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(t.space.s3),
    ) {
        // decorative, as a list row's lead (spec/08 §14.4): the row's name is the title; the Row mirrors it in RTL
        if (icon != null) Icon(icon, contentDescription = null, tint = c.textMuted, modifier = Modifier.size(t.size.iconLg))
        Column(Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(t.space.s0_5)) {
            SbWrapText(title, ty.body, if (enabled) c.text else c.textMuted)
            if (help != null) SbWrapText(help, ty.caption, c.textMuted)
        }
        Switch(
            checked = checked,
            onCheckedChange = null,
            enabled = enabled,
            colors = SbControlColors.switch(),
            thumbContent = if (checked) {
                { Icon(SebaroIcons.Outline16.Check, contentDescription = null) }
            } else {
                null
            },
        )
    }
}

