/**
 * A check row (spec/02 §2.4): the checkbox at the start (no fill, edge and check accent when checked), [title] in body and
 * [help] in caption textMuted; ≥ 48 dp (56 dp with help), the whole row toggles, pressed pressedFill, no ripple;
 * TalkBack „angekreuzt“ / „nicht angekreuzt“ from the words table.
 */
@Composable
fun SbCheckRow(
    title: String,
    checked: Boolean,
    onChange: (Boolean) -> Unit,
    modifier: Modifier = Modifier,
    help: String? = null,
    enabled: Boolean = true,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val m = sbMessages()
    val interaction = remember { MutableInteractionSource() }
    val pressed by interaction.collectIsPressedAsState()
    Row(
        modifier
            .fillMaxWidth()
            .heightIn(min = if (help != null) t.size.controlLg else t.size.controlMd)
            .background(if (pressed && enabled) c.pressedFill else Color.Transparent)
            .sbFocusRingInset(interaction)
            .toggleable(
                value = checked,
                interactionSource = interaction,
                indication = null,
                enabled = enabled,
                role = Role.Checkbox,
                onValueChange = onChange,
            )
            .semantics { stateDescription = if (checked) m.checkOn else m.checkOff }
            .padding(horizontal = t.spacing.gutter, vertical = t.space.s1),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(t.space.s3),
    ) {
        Checkbox(checked = checked, onCheckedChange = null, enabled = enabled, colors = SbControlColors.checkbox())
        Column(Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(t.space.s0_5)) {
            SbWrapText(title, ty.body, if (enabled) c.text else c.textMuted)
            if (help != null) SbWrapText(help, ty.caption, c.textMuted)
        }
    }
}

